def sha(b):
    return hashlib.sha256(b).hexdigest()

def canon_bytes(v):
    if isinstance(v, str):
        return v.encode('utf-8')
    return json.dumps(v, sort_keys=True, ensure_ascii=False, separators=(',', ':')).encode('utf-8')

def canon(v):
    return sha(canon_bytes(v))

