# ---------------------------------------------------------------- leaf rule
# LEAF RULE (declared): descend every mapping by key; descend a list of mappings by a
# selector [X] where X is the value of the element's 'id' key, else its 'kind', else its
# 'name' (only if unique among siblings), else 'item N' (1-based); descend a list of
# scalars by 'item N'. A leaf is every scalar node (string, number, boolean, null) and
# every empty mapping/list reached this way, including the selector key itself.
SELKEYS = ('id', 'kind', 'name')
def sel_key(lst):
    if not lst or not all(isinstance(e, dict) for e in lst):
        return None
    for k in SELKEYS:
        vals = [e.get(k) for e in lst]
        if all(isinstance(v, str) for v in vals) and len(set(vals)) == len(vals):
            return k
    return None

def children(node, path):
    if isinstance(node, dict):
        for k, v in node.items():
            yield (path + '.' + k if path else k), v
    elif isinstance(node, list):
        sk = sel_key(node)
        for i, e in enumerate(node):
            if sk:
                yield path + '[' + e[sk] + ']', e
            else:
                yield path + ' item %d' % (i + 1), e

def leaves(node, path, acc):
    if isinstance(node, (dict, list)) and node:
        for p, v in children(node, path):
            leaves(v, p, acc)
    else:
        acc[path] = node
    return acc

