# ---------------------------------------------------------------- path resolver
TOK = re.compile(r'^([A-Za-z0-9_\-]+)((?:\[[^\]]+\])*)((?: item \d+)?)$')
def split_path(p):
    # split on '.' not inside [...]
    parts, cur, depth = [], '', 0
    for ch in p:
        if ch == '[': depth += 1
        if ch == ']': depth -= 1
        if ch == '.' and depth == 0:
            parts.append(cur); cur = ''
        else:
            cur += ch
    parts.append(cur)
    return parts

def get(file, path):
    node = TOP[file]
    if path == '':
        return node
    for part in split_path(path):
        m = TOK.match(part)
        if not m:
            raise KeyError('bad token %r in %r' % (part, path))
        name, sels, item = m.groups()
        if not isinstance(node, dict) or name not in node:
            raise KeyError('no key %r in %s:%s' % (name, file, path))
        node = node[name]
        for s in re.findall(r'\[([^\]]+)\]', sels):
            if isinstance(node, list):
                sk = sel_key(node)
                cand = [e for e in node if isinstance(e, dict) and any(e.get(k) == s for k in SELKEYS)]
                if len(cand) != 1:
                    raise KeyError('selector %r unresolved in %s:%s' % (s, file, path))
                node = cand[0]
            elif isinstance(node, dict) and s in node:
                node = node[s]
            else:
                raise KeyError('selector %r on non-list in %s:%s' % (s, file, path))
        if item:
            n = int(item.split()[-1])
            if not isinstance(node, list) or n < 1 or n > len(node):
                raise KeyError('item %d out of range in %s:%s' % (n, file, path))
            node = node[n - 1]
    return node

def exists(file, path):
