        return False

# ---------------------------------------------------------------- spans
def span_of(text, frm, thr):
    """Span convention of narrow incorporates.span_hash_convention (incorporated by gated)."""
    n_from = text.count(frm)
    i = text.find(frm)
    if i < 0:
        return None, n_from, None
    j = text.find(thr, i)
    if j < 0:
        return None, n_from, None
    return (i, j + len(thr)), n_from, text.count(thr)

