def add_span(rule_id, layer, file, field, frm, thr, repl, repl_loc, declared):
    SPANS.setdefault((file, field), []).append(dict(id=rule_id, layer=layer, frm=frm, thr=thr, repl=repl,
                                                     repl_loc=repl_loc, declared=declared))
for r in N['span_rules']:
