        repl, loc, layer = threshold_index_text, 'gated:corrective.threshold_index.text', 'gated'
    add_span(r['id'], layer, 'typed', r['field'], r['from'], r['through'], repl, loc, r['replaced_span_sha256'])
for r in G['gated_span_rules']:
    f = 'typed' if r['file'].endswith('AMD-20260926-typed.yaml') else 'narrow'
    add_span(r['id'], 'gated', f, r['field'], r['from'], r['through'], r['replacement'],
             'gated:gated_span_rules[%s].replacement' % r['id'], r['replaced_span_sha256'])

def assemble(file, field):
    base = get(file, field)
    rules = SPANS.get((file, field), [])
    locs = []
    for rl in rules:
        pos, nf, nt = span_of(base, rl['frm'], rl['thr'])
        chk = dict(rule=rl['id'], file=file, field=field, from_count=nf, through_count=nt,
                   found=pos is not None)
        if pos:
            st = base[pos[0]:pos[1]]
            chk.update(span_text=st, computed_sha256=sha(st.encode('utf-8')), declared_sha256=rl['declared'],
                       sha_match=sha(st.encode('utf-8')) == rl['declared'], start=pos[0], end=pos[1])
        locs.append((pos, rl, chk))
    locs.sort(key=lambda x: x[0][0] if x[0] else -1)
    pieces_out, s, cur = [], '', 0
    for pos, rl, chk in locs:
        if not pos: continue
        pieces_out.append(base[cur:pos[0]])
        s += base[cur:pos[0]] + rl['repl']
        cur = pos[1]
    pieces_out.append(base[cur:])
    s += base[cur:]
    return s, pieces_out, [c for _, _, c in locs]

