# ---------------------------------------------------------------- effective value of any container/field
def eff(file, path, node=None):
    if (file, path) in WHOLE:
        f2, p2 = WHOLE[(file, path)]
        return eff(f2, p2)
    if node is None:
        node = get(file, path)
    if isinstance(node, str) and (file, path) in SPANS:
        return assemble(file, path)[0]
    if isinstance(node, dict):
        return {k: eff(file, p, v) for (p, v), k in zip(children(node, path), node.keys())}
    if isinstance(node, list):
        return [eff(file, p, v) for p, v in children(node, path)]
    return node

def union_of(file, path, held_eff):
