def cover(file, base, excl=None):
    hit = []
    for lp in LEAVES[file]:
        if lp == base or lp.startswith(base + '.') or lp.startswith(base + '[') or lp.startswith(base + ' item '):
            if excl and (lp == excl or lp.startswith(excl + '.') or lp.startswith(excl + '[') or lp.startswith(excl + ' item ')):
                continue
            hit.append(lp)
    for h in hit: covered[file].add(h)
    return hit

def rec_value(v):
    return dict(effective_text=v, sha256=canon(v), kind='string' if isinstance(v, str) else 'json')

for idx, r in enumerate(rows, 1):
    fld, layer = r['field'], r['layer']
    R = dict(row=idx, field=fld, table_layer=layer, table_via=r['via'])
    try:
        if fld.startswith('file:'):
            R.update(governing_file='none', my_layer=layer, determination='no field of the named file governs',
                     clauses=['typed supersedes_fields item 21' if 'bands' in fld else 'narrow governs_nothing item 2; gated governs_nothing item 2; typed predecessor_status'],
                     my_leaves=[], **rec_value(None))
            records.append(R); continue
        prefix, rest = fld.split(':', 1)
        excl = None
        if ' except ' in rest:
            base, ex = rest.split(' except ', 1)
            excl = base + ex if ex.startswith('.') else base + ' ' + ex if ex.startswith('item') else base + '.' + ex
            # "rows except item 6.outcome" -> base 'rows', excluded 'rows item 6.outcome'
            if ex.startswith('item'):
                excl = base + ' ' + ex
            qual = None; spans = None
        else:
            m = QUAL.match(rest)
            base, qual, spans = m.group(1), m.group(2), m.group(3)
        file = prefix
        if not exists(file, base):
            unresolved_rows.append(idx)
            R.update(error='path does not resolve in %s' % file)
            records.append(R); continue
        R['my_leaves'] = cover(file, base, excl)
        top = split_path(base)[0]
        topname = TOK.match(top).group(1)

        # ---- span rows
        if qual == 'span':
            sid = spans.strip()
            rl = [x for x in SPANS[(file, base)] if x['id'] == sid][0]
            full, pieces, chks = assemble(file, base)
            R.update(governing_file=FNAME['gated'] if rl['layer'] == 'gated' else FNAME['narrow'],
                     my_layer=rl['layer'], replacement_location=rl['repl_loc'],
                     clauses=['%s span rule %s' % (rl['layer'], sid), 'narrow incorporates.span_hash_convention (incorporated by gated incorporates_by_hash.span_hash_convention)']
