            if u is not None:
                R.update(union_with_additions=u, union_sha256=canon(u), additions=ADDS[(file, base)])
            records.append(R); continue
        if qual in ('outside span', 'outside spans'):
            full, pieces, chks = assemble(file, base)
            lay = 'typed-by-hash' if file == 'typed' else 'narrow-by-hash'
            R.update(governing_file=FNAME[file], my_layer=lay,
                     clauses=['held field outside the span(s) %s stays incorporated by hash' % spans],
