                     outside_concatenated_sha256=canon(''.join(pieces)),
                     assembled_whole=full, assembled_whole_sha256=canon(full), **rec_value(pieces))
            u = union_of(file, base, full)
            if u is not None:
                R.update(union_with_additions=u, union_sha256=canon(u), additions=ADDS[(file, base)])
            records.append(R); continue

        # ---- except rows
        if excl is not None:
            node = eff(file, base)
            # remove excluded sub-path from a deep copy
            import copy
            node = copy.deepcopy(get(file, base))
            ex_rel = excl[len(base):]
            if ex_rel.startswith('.'):
                del node[ex_rel[1:]]
            else:
                mm = re.match(r' item (\d+)(?:\.(.+))?$', ex_rel)
                i = int(mm.group(1)) - 1
                if mm.group(2): del node[i][mm.group(2)]
                else: del node[i]
            R.update(governing_file=FNAME[file], my_layer='narrow-by-hash',
                     clauses=['incorporated by hash; excluded sub-path %s is superseded' % excl], **rec_value(node))
            records.append(R); continue

        # ---- v1 rows
        if file == 'v1':
            sup = v1_super(base)
            if sup:
                gf, locs, val, clause = sup
                R.update(governing_file=FNAME['typed'], my_layer='typed-by-hash', replacement_location=locs,
                         clauses=[clause, 'gated precedence (latest superseding layer governs)'], v1_text_sha256=canon(get('v1', base)),
                         **rec_value(val))
            else:
                R.update(governing_file=FNAME['v1'], my_layer='v1',
                         clauses=['no typed supersedes_fields item names it', 'gated precedence'], **rec_value(get('v1', base)))
            records.append(R); continue

        # ---- typed envelope / identity
        if file == 'typed' and topname in TYPED_ENV:
            sub = base[len(topname):]
            if topname == 'cites':
                tgt = 'cites'
            else:
                tgt = topname + sub
            if exists('gated', tgt):
                R.update(governing_file=FNAME['gated'], my_layer='gated', replacement_location='gated:' + tgt,
                         clauses=['narrow envelope_not_incorporated (typed envelope list) as amended by gated span G-ENV',
                                  'gated narrow_envelope_not_incorporated.typed_envelope'] + (['item-level role mapping unavailable: gated cites is read whole'] if topname == 'cites' else []),
                         typed_text_sha256=canon(get('typed', base)), **rec_value(eff('gated', tgt)))
            else:
                R.update(governing_file='none', my_layer='gated (no field of the same role exists)', replacement_location=None,
                         clauses=['narrow envelope_not_incorporated: typed field NOT incorporated',
                                  'gated span G-ENV: "The field of the same role in AMD-...-gated governs instead" -- gated has no field of that role'],
                         typed_text_sha256=canon(get('typed', base)), **rec_value(None))
            records.append(R); continue
        if file == 'typed' and topname in IDENTITY:
            R.update(governing_file=FNAME['typed'], my_layer='typed-by-hash',
                     clauses=['not in narrow envelope_not_incorporated.fields; incorporated by narrow what_is_incorporated',
                              'gated narrow_envelope_not_incorporated.rule identity sentence names narrow and gated files only'],
                     gated_same_value=(get('typed', base) == get('gated', base)), **rec_value(get('typed', base)))
            records.append(R); continue

        # ---- narrow envelope / identity
        if file == 'narrow' and topname in NARROW_ENV + IDENTITY:
            sub = base[len(topname):]
            tgt = 'cites' if topname == 'cites' else topname + sub
            R.update(governing_file=FNAME['gated'], my_layer='gated', replacement_location='gated:' + tgt,
                     clauses=['gated narrow_envelope_not_incorporated.rule / .fields'] + (['item-level role mapping unavailable: gated cites is read whole'] if topname == 'cites' else []),
                     narrow_text_sha256=canon(get('narrow', base)), **rec_value(eff('gated', tgt)))
            records.append(R); continue

        # ---- whole replacements
        if (file, base) in WHOLE:
            f2, p2 = WHOLE[(file, base)]
            lay = {'narrow': 'narrow-by-hash', 'gated': 'gated'}[f2]
            val = eff(f2, p2)
            R.update(governing_file=FNAME[f2], my_layer=lay, replacement_location='%s:%s' % (f2, p2),
                     clauses=['%s supersedes_fields (whole) -> %s' % (f2, p2)], held_text_sha256=canon(get(file, base)),
                     **rec_value(val))
            u = union_of(f2, p2, val)
            if u is not None:
                R.update(union_with_additions=u, union_sha256=canon(u), additions=ADDS[(f2, p2)])
            records.append(R); continue

        # ---- ordinary rows
        val = eff(file, base)
        lay = {'typed': 'typed-by-hash', 'narrow': 'narrow-by-hash', 'gated': 'gated'}[file]
        R.update(governing_file=FNAME[file], my_layer=lay,
                 clauses={'typed': ['narrow incorporates.what_is_incorporated (as amended by G-WII); not superseded by narrow or gated'],
                          'narrow': ['gated incorporates_by_hash.what_is_incorporated; not superseded by gated'],
                          'gated': ['gated precedence: this file']}[file], **rec_value(val))
        u = union_of(file, base, val)
        if u is not None:
            R.update(union_with_additions=u, union_sha256=canon(u), additions=ADDS[(file, base)])
        parent_adds = [k for k in ADDS if k[0] == file and (base.startswith(k[1] + '.') or base.startswith(k[1] + '[') or base.startswith(k[1] + ' item '))]
        if parent_adds:
            R['ancestor_path_has_additions'] = [dict(path=k[1], additions=ADDS[k]) for k in parent_adds]
        records.append(R)
    except Exception as e:
        R.update(error=repr(e)); records.append(R)

out['rows'] = records
out['unresolved_rows'] = unresolved_rows
